function result=v4TrackAStage55FromPreambleRate(packet,c,p,b,version)
s=packet.schedule;cfo=b.cfoAtQuarterStartBins;rate=max(-p.maximumRateBinsPerSec,min(p.maximumRateBinsPerSec,b.rateBinsPerSec));phase=0;history=repmat(struct('measurementTimeSec',0,'cfoCandidateBins',0,'peakRatio',0),0,1);detected=nan(23,1);estimated=nan(23,1);accepted=false(23,1);labels=nan(23,1);rejected=0;lost=false;
for row=s.quarterDownRow:numel(s.kind),first=s.startSample(row)+1;rx=packet.rx(first:first+s.sampleCount(row)-1).';duration=numel(rx)/c.sampleRateHz;center=cfo+rate*duration/2;y=localComp(rx,phase,center,rate,c);oldCfo=cfo;oldRate=rate;if s.kind(row)=="data",d=s.dataIndex(row);decision=v4SymbolLikelihood(y,c,packet.noiseVariance);detected(d)=decision.physicalBin;estimated(d)=center;if ~lost,residual=v4PhaseRotationEstimate(y,decision.physicalBin,c,(-1:p.residualStepBins:1).');q=v4TrackASymbolQuality(decision,residual,p);if q.accept,m=struct('measurementTimeSec',s.centerTimeOffsetSec(row),'cfoCandidateBins',center+residual.offsetBins,'peakRatio',q.peakRatio);proposed=[history;m];if numel(proposed)>8,proposed=proposed(end-7:end);end;if numel(proposed)>=2,fit=v4TrackACommittedHistoryFit(proposed,(s.startSample(row)+s.sampleCount(row))/c.sampleRateHz,p);valid=fit.withinRateBound&&fit.withinResidualBound;else,fit=struct('cfoBins',m.cfoCandidateBins+rate*duration/2,'rateBinsPerSec',rate);valid=true;end;if valid,accepted(d)=true;labels(d)=decision.physicalBin;history=proposed;cfo=fit.cfoBins;rate=fit.rateBinsPerSec;rejected=0;else,rejected=rejected+1;end;else,rejected=rejected+1;end;if rejected>=3,lost=true;end;end;end;phase=mod(phase+2*pi*(oldCfo*duration/c.symbolDurationSec+0.5*oldRate*duration^2/c.symbolDurationSec),2*pi);if ~(s.kind(row)=="data"&&accepted(s.dataIndex(row))),cfo=oldCfo+oldRate*duration;end;end
result=struct('methodName','Stage55-VP-quality-SER-SF12-noLDRO','algorithmVersion',version,'detectedPhysicalBins',detected,'estimatedCfoBins',estimated,'virtualPilotAccepted',accepted,'vpUsedLabel',labels,'bootstrap',b,'initialRateBinsPerSec',b.rateBinsPerSec,'finalLost',lost,'usesTruth',false,'usesHamming',false,'usesMidambleObservation',false);
end
function y=localComp(rx,phase,cfo,rate,c),n=0:numel(rx)-1;t=n/c.sampleRateHz;duration=numel(rx)/c.sampleRateHz;start=cfo-rate*duration/2;y=rx.*exp(-1i*(phase+2*pi*(start*t/c.symbolDurationSec+0.5*rate*t.^2/c.symbolDurationSec)));end
